.varlab-container {
    padding: 24px;
    background: linear-gradient(180deg, #0f172a 0%, #1e293b 60%, #273449 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e2e8f0;
}

.varlab-container h1,
.varlab-container h3 {
    margin: 0;
}

.varlab-header {
    background: #111c2f;
    border: 1px solid #263448;
    border-left: 5px solid #38bdf8;
    padding: 24px 28px;
    margin-bottom: 22px;
    border-radius: 6px;
    box-shadow: 0 4px 16px rgba(0,0,0,0.25);
}
.varlab-header-badge {
    display: inline-block;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #38bdf8;
    background: rgba(56,189,248,0.1);
    padding: 4px 10px;
    border-radius: 3px;
    margin-bottom: 12px;
    font-weight: 600;
}
.varlab-header h1 {
    color: #f1f5f9;
    font-size: 1.8rem;
    letter-spacing: 0.02em;
    font-weight: 700;
}
.varlab-subtitle {
    color: #94a3b8;
    margin: 6px 0 0;
    font-size: 0.95rem;
    letter-spacing: 0.03em;
}

.varlab-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1e2a3f;
    border: 1px solid #2d3e58;
    border-radius: 6px;
    padding: 12px 20px;
    margin-bottom: 22px;
    gap: 16px;
}
.varlab-period-block {
    display: flex;
    align-items: center;
    gap: 10px;
}
.varlab-period-label {
    font-size: 0.75rem;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: #94a3b8;
}
.varlab-period-value {
    color: #f8fafc;
    font-weight: 700;
    font-size: 1.05rem;
}
.varlab-period-hint {
    color: #fbbf24;
    font-size: 0.88rem;
    font-style: italic;
    text-align: right;
    flex: 1;
}

.varlab-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}
.varlab-kpi-card {
    background: #1a2438;
    border: 1px solid #273449;
    border-radius: 6px;
    padding: 18px 18px 16px;
    position: relative;
    overflow: hidden;
}
.varlab-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #38bdf8, #818cf8);
}
.varlab-kpi-primary::before {
    background: linear-gradient(90deg, #34d399, #38bdf8);
}
.varlab-kpi-label {
    color: #94a3b8;
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 600;
    margin-bottom: 10px;
}
.varlab-kpi-value {
    color: #f8fafc;
    font-size: 2rem;
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: -0.02em;
}
.varlab-kpi-primary .varlab-kpi-value {
    color: #34d399;
}
.varlab-kpi-sublabel {
    color: #64748b;
    font-size: 0.72rem;
    margin-top: 6px;
    letter-spacing: 0.05em;
}

.varlab-section {
    background: #141e31;
    border: 1px solid #263448;
    border-radius: 8px;
    padding: 22px 24px;
    margin-bottom: 22px;
}
.varlab-section-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 18px;
    border-bottom: 1px solid #263448;
    padding-bottom: 12px;
}
.varlab-section-head h3 {
    color: #f1f5f9;
    font-size: 1.05rem;
    letter-spacing: 0.03em;
    font-weight: 600;
}
.varlab-section-tag {
    color: #64748b;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

.varlab-line-grid {
    display: grid;
    grid-template-columns: 1fr auto 1fr auto 1fr;
    gap: 14px;
    align-items: stretch;
}
.varlab-station {
    background: #1e2a42;
    border: 1px solid #334155;
    border-radius: 6px;
    padding: 16px 16px 14px;
    display: flex;
    flex-direction: column;
}
.varlab-station-head {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
}
.varlab-station-index {
    width: 28px;
    height: 28px;
    border-radius: 4px;
    background: #38bdf8;
    color: #0f172a;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}
.varlab-station-name {
    color: #e2e8f0;
    font-weight: 600;
    letter-spacing: 0.03em;
}
.varlab-station-state {
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    font-weight: 600;
    padding: 4px 8px;
    border-radius: 3px;
    display: inline-block;
    margin-bottom: 10px;
    background: rgba(148,163,184,0.15);
    color: #94a3b8;
}
.varlab-station-state.state-processing {
    background: rgba(251,191,36,0.15);
    color: #fbbf24;
}
.varlab-station-state.state-blocked {
    background: rgba(248,113,113,0.15);
    color: #f87171;
}
.varlab-station-state.state-starved {
    background: rgba(96,165,250,0.15);
    color: #60a5fa;
}
.varlab-station-bar {
    width: 100%;
    height: 6px;
    background: #0f172a;
    border-radius: 3px;
    margin-bottom: 12px;
    overflow: hidden;
}
.varlab-station-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #34d399, #38bdf8);
    transition: width 0.3s ease;
}
.varlab-station-rows {
    display: flex;
    flex-direction: column;
    gap: 6px;
    font-size: 0.82rem;
}
.varlab-station-row {
    display: flex;
    justify-content: space-between;
    color: #94a3b8;
}
.varlab-station-row b {
    color: #f1f5f9;
    font-weight: 600;
}

.varlab-buffer {
    background: #0f1a2e;
    border: 1px dashed #334155;
    border-radius: 6px;
    padding: 14px 14px;
    min-width: 110px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    text-align: center;
}
.varlab-buffer-label {
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #64748b;
    font-weight: 600;
}
.varlab-buffer-cap,
.varlab-buffer-occ {
    font-size: 0.78rem;
    color: #94a3b8;
}
.varlab-buffer-cap b,
.varlab-buffer-occ b {
    color: #f1f5f9;
    font-weight: 600;
}

.varlab-control-group {
    margin-bottom: 18px;
}
.varlab-control-group:last-of-type {
    margin-bottom: 8px;
}
.varlab-control-group-label {
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #38bdf8;
    font-weight: 600;
    margin-bottom: 10px;
}
.varlab-control-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
}
.varlab-control-field label {
    display: block;
    font-size: 0.78rem;
    color: #cbd5e1;
    margin-bottom: 6px;
    font-weight: 500;
}
.varlab-controls input[type="number"],
.varlab-controls select {
    width: 100%;
    background: #0f172a;
    border: 1px solid #334155;
    color: #f1f5f9;
    border-radius: 4px;
    padding: 9px 12px;
    font-size: 0.9rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.varlab-controls input[type="number"]:focus,
.varlab-controls select:focus {
    outline: none;
    border-color: #38bdf8;
    box-shadow: 0 0 0 2px rgba(56,189,248,0.25);
}
.varlab-controls select option {
    background: #0f172a;
    color: #f1f5f9;
}

.varlab-btn-row {
    display: flex;
    gap: 12px;
    margin-top: 18px;
    flex-wrap: wrap;
}
.varlab-btn-primary {
    background: #38bdf8;
    color: #0f172a;
    border: none;
    padding: 10px 22px;
    border-radius: 4px;
    font-weight: 700;
    letter-spacing: 0.05em;
    font-size: 0.88rem;
    text-transform: uppercase;
    transition: background 0.2s ease, transform 0.15s ease;
}
.varlab-btn-primary:hover {
    background: #0ea5e9;
    transform: translateY(-1px);
}
.varlab-btn-secondary {
    background: transparent;
    color: #94a3b8;
    border: 1px solid #334155;
    padding: 10px 18px;
    border-radius: 4px;
    font-size: 0.82rem;
    letter-spacing: 0.05em;
}
.varlab-btn-secondary:hover {
    color: #f1f5f9;
    border-color: #64748b;
}

.varlab-history {
    overflow-x: auto;
}
.varlab-history table {
    width: 100%;
    color: #cbd5e1;
    border-collapse: collapse;
    font-size: 0.85rem;
}
.varlab-history table thead th {
    background: #0f1a2e;
    color: #38bdf8;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 10px 12px;
    border-bottom: 1px solid #263448;
    text-align: left;
    font-weight: 600;
}
.varlab-history table tbody td {
    padding: 9px 12px;
    border-bottom: 1px solid #1f2a3f;
}
.varlab-history table tbody tr:hover {
    background: rgba(56,189,248,0.05);
}

.varlab-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}
.varlab-chart-card {
    background: #141e31;
    border: 1px solid #263448;
    border-radius: 8px;
    padding: 18px 20px;
    height: 320px;
    display: flex;
    flex-direction: column;
}
.varlab-chart-head {
    color: #e2e8f0;
    font-size: 0.9rem;
    font-weight: 600;
    letter-spacing: 0.05em;
    margin-bottom: 12px;
    padding-bottom: 10px;
    border-bottom: 1px solid #263448;
}
.varlab-chart-card canvas {
    flex: 1;
    min-height: 0;
}

@media (max-width: 900px) {
    .varlab-line-grid {
        grid-template-columns: 1fr;
    }
    .varlab-buffer {
        flex-direction: row;
        justify-content: space-around;
        padding: 10px 14px;
    }
    .varlab-period-bar {
        flex-direction: column;
        align-items: flex-start;
    }
    .varlab-period-hint {
        text-align: left;
    }
}
@media (max-width: 768px) {
    .varlab-container { padding: 16px; }
    .varlab-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .varlab-kpi-value { font-size: 1.5rem; }
    .varlab-header h1 { font-size: 1.4rem; }
}

